CREATE TABLE IF NOT EXISTS schools (id TEXT PRIMARY KEY, name TEXT NOT NULL, motto TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS app_settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS academic_sessions (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), name TEXT NOT NULL UNIQUE, current_term INTEGER NOT NULL CHECK(current_term BETWEEN 1 AND 3));
CREATE TABLE IF NOT EXISTS classes (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS subjects (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), email TEXT NOT NULL UNIQUE, name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('ADMIN','TEACHER','STUDENT')), status TEXT NOT NULL CHECK(status IN ('ACTIVE','PENDING','SUSPENDED','DEACTIVATED','REJECTED','REMOVED')), password_hash TEXT NOT NULL, profile TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS enrolments (id TEXT PRIMARY KEY, student_id TEXT NOT NULL REFERENCES users(id), session_id TEXT NOT NULL REFERENCES academic_sessions(id), class_id TEXT NOT NULL REFERENCES classes(id), UNIQUE(student_id,session_id));
CREATE TABLE IF NOT EXISTS teacher_assignments (id TEXT PRIMARY KEY, teacher_id TEXT NOT NULL REFERENCES users(id), session_id TEXT NOT NULL REFERENCES academic_sessions(id), class_id TEXT NOT NULL REFERENCES classes(id), subject_id TEXT NOT NULL REFERENCES subjects(id), UNIQUE(teacher_id,session_id,class_id,subject_id));
CREATE TABLE IF NOT EXISTS courses (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES academic_sessions(id), class_id TEXT NOT NULL REFERENCES classes(id), subject_id TEXT NOT NULL REFERENCES subjects(id), term INTEGER NOT NULL CHECK(term BETWEEN 1 AND 3), UNIQUE(session_id,class_id,subject_id,term));
CREATE TABLE IF NOT EXISTS course_weeks (id TEXT PRIMARY KEY, course_id TEXT NOT NULL REFERENCES courses(id) ON DELETE CASCADE, week_number INTEGER NOT NULL, title TEXT NOT NULL, content TEXT NOT NULL, UNIQUE(course_id,week_number));
CREATE TABLE IF NOT EXISTS lessons (id TEXT PRIMARY KEY, week_id TEXT NOT NULL REFERENCES course_weeks(id) ON DELETE CASCADE, lesson_key TEXT NOT NULL, title TEXT NOT NULL, content TEXT NOT NULL, UNIQUE(week_id,lesson_key));
CREATE TABLE IF NOT EXISTS question_items (id TEXT PRIMARY KEY, week_id TEXT NOT NULL REFERENCES course_weeks(id) ON DELETE CASCADE, lesson_id TEXT REFERENCES lessons(id) ON DELETE CASCADE, question_key TEXT NOT NULL, stage TEXT NOT NULL, difficulty TEXT NOT NULL, question_type TEXT NOT NULL, content TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS question_scope ON question_items(lesson_id,stage,difficulty);
CREATE TABLE IF NOT EXISTS access_rules (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES academic_sessions(id), class_id TEXT NOT NULL REFERENCES classes(id), subject_id TEXT NOT NULL REFERENCES subjects(id), term INTEGER NOT NULL, content TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS assignments (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES academic_sessions(id), class_id TEXT NOT NULL REFERENCES classes(id), subject_id TEXT NOT NULL REFERENCES subjects(id), term INTEGER NOT NULL, teacher_id TEXT REFERENCES users(id), content TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS files (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES academic_sessions(id), class_id TEXT NOT NULL REFERENCES classes(id), subject_id TEXT NOT NULL REFERENCES subjects(id), term INTEGER NOT NULL, owner_id TEXT NOT NULL REFERENCES users(id), content TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS submissions (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES academic_sessions(id), class_id TEXT NOT NULL REFERENCES classes(id), subject_id TEXT NOT NULL REFERENCES subjects(id), term INTEGER NOT NULL, student_id TEXT NOT NULL REFERENCES users(id), assignment_id TEXT REFERENCES assignments(id), content TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS submission_versions (id TEXT PRIMARY KEY, submission_id TEXT NOT NULL REFERENCES submissions(id), content TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS marking_history (id TEXT PRIMARY KEY, submission_id TEXT NOT NULL REFERENCES submissions(id), teacher_id TEXT NOT NULL REFERENCES users(id), content TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS progress (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES academic_sessions(id), class_id TEXT NOT NULL REFERENCES classes(id), subject_id TEXT NOT NULL REFERENCES subjects(id), term INTEGER NOT NULL, student_id TEXT NOT NULL REFERENCES users(id), content TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS practice_attempts (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES academic_sessions(id), class_id TEXT NOT NULL REFERENCES classes(id), subject_id TEXT NOT NULL REFERENCES subjects(id), term INTEGER NOT NULL, student_id TEXT NOT NULL REFERENCES users(id), content TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS assessment_attempts (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES academic_sessions(id), class_id TEXT NOT NULL REFERENCES classes(id), subject_id TEXT NOT NULL REFERENCES subjects(id), term INTEGER NOT NULL, student_id TEXT NOT NULL REFERENCES users(id), content TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reflections (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES academic_sessions(id), class_id TEXT NOT NULL REFERENCES classes(id), subject_id TEXT NOT NULL REFERENCES subjects(id), term INTEGER NOT NULL, student_id TEXT NOT NULL REFERENCES users(id), content TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS discussions (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES academic_sessions(id), class_id TEXT NOT NULL REFERENCES classes(id), subject_id TEXT NOT NULL REFERENCES subjects(id), term INTEGER NOT NULL, student_id TEXT NOT NULL REFERENCES users(id), content TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS scores (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES academic_sessions(id), class_id TEXT NOT NULL REFERENCES classes(id), subject_id TEXT NOT NULL REFERENCES subjects(id), term INTEGER NOT NULL, student_id TEXT NOT NULL REFERENCES users(id), content TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS resources (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES academic_sessions(id), class_id TEXT NOT NULL REFERENCES classes(id), subject_id TEXT NOT NULL REFERENCES subjects(id), term INTEGER NOT NULL, content TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS lesson_releases (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES academic_sessions(id), class_id TEXT NOT NULL REFERENCES classes(id), subject_id TEXT NOT NULL REFERENCES subjects(id), term INTEGER NOT NULL, content TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS announcements (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES academic_sessions(id), class_id TEXT NOT NULL REFERENCES classes(id), subject_id TEXT NOT NULL REFERENCES subjects(id), term INTEGER NOT NULL, content TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notifications (id TEXT PRIMARY KEY, recipient_id TEXT NOT NULL REFERENCES users(id), content TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_logs (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), occurred_at TEXT NOT NULL, content TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS recovery_tokens (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires_at TEXT NOT NULL, content TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS auth_sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires_at BIGINT NOT NULL, content TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS auth_expiry ON auth_sessions(expires_at);
CREATE INDEX IF NOT EXISTS submission_privacy ON submissions(student_id,session_id,class_id,subject_id,term);
CREATE INDEX IF NOT EXISTS assessment_privacy ON assessment_attempts(student_id,session_id,term);
CREATE INDEX IF NOT EXISTS score_privacy ON scores(student_id,session_id,term);
